import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-view-job',
  templateUrl: './view-job.component.html',
  styleUrls: ['./view-job.component.css']
})
export class ViewJobComponent {

constructor(private jobService : JobService, private route : ActivatedRoute,
    private companyService: CompanyService,
    private jobSeekerService: JobseekerService,
    private router: Router
){}




job! : Job;
jobSkills : any[] = [];

getJobByJobId(id : number){
  this.jobService.getJobById(id).subscribe({
    next : (result) => {
  this.job = result;
  this.jobSkills = this.job.skills;
    },
    error : (err) =>{
    console.log(err);

    }
  });
}


 allJobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';



  ngOnInit(): void {

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');
      const id = Number(localStorage.getItem('id'));

      if (role === 'COMPANY') {

        this.profileRoute = '/company/dashboard';

        this.companyService.getCompanyById(id).subscribe({
          next: (company: any) => {
            if (company?.companyName) {
              this.initials = company.companyName
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });

      } else {

        this.profileRoute = '/seeker/dashboard';

        this.jobSeekerService.getJobSeekerById(id).subscribe({
          next: (user: any) => {


            const name =
              user.userName ??
              `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();

            if (name) {
              this.initials = name
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });
      }
    }

  const jobId = Number(this.route.snapshot.paramMap.get("id"));
  const jobSeekerId = Number(localStorage.getItem("id"));

  this.jobService.getSavedJobs(jobSeekerId).subscribe({
    next: (jobs: Job[]) => {
      this.isjobSaved = jobs.some(job => Number(job.jobId) === jobId);
    },
    error: (err) => console.error(err)
  });   


    this.getJobByJobId(jobId);
  }




  logout(): void {
    localStorage.clear();
    this.router.navigate(['/']);
  }

  goToProfile(): void {
    this.router.navigate([this.profileRoute]);
  };

isjobSaved= false;
  saveJobToProfile(){

    const jobId = Number(this.route.snapshot.paramMap.get("id"));
    const jobSeekerId = Number(localStorage.getItem("id"));





    this.jobService.saveJobToProfile(jobId, jobSeekerId).subscribe({
      next: (result) => {
        this.isjobSaved = true;
      },
      error: (err) => {
        console.log(err);
      }
    });

  }


}
